choose.when:
SELECT grpcd as grpcd, grpcd as code, grpnm as grpnm, grpnm as remark, dspord, useyn FROM haaa810t_tbl WHERE 1=1
AND upmucd = #{gbncd}
ORDER BY dspord

mapper.select:
SELECT cdtype, codecd, codenm, remark, dspord, useyn
FROM haba900t_tbl
WHERE 1=1

    AND cdtype = #{cdkind}


    AND codecd = #{code}

ORDER BY dspord

